import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.DTisvdQ9.js";const a="/doc/assets/designer-01-empty-interface.Ba_TLJO4.png",c="/doc/assets/designer-02-test-venue.B3kwgF_T.png",l="/doc/assets/designer-04-lasso-active.rALt5DKa.png",s="/doc/assets/designer-05-node-tool.C_TeM1lX.png",i="/doc/assets/designer-06-seats-edit-mode.z12qrM4-.png",n="/doc/assets/designer-07-category-modal.8asJHiVM.png",h="/doc/assets/designer-08-labeling-modal.h9GjtNsv.png",g="/doc/assets/designer-09-gongti-full.Ci_4iqN3.png",C=JSON.parse('{"title":"设计端操作说明","description":"","frontmatter":{},"headers":[],"relativePath":"designer/operations.md","filePath":"designer/operations.md","lastUpdated":1787039578000}'),p={name:"designer/operations.md"};function b(u,t,m,q,f,k){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="设计端操作说明" tabindex="-1">设计端操作说明 <a class="header-anchor" href="#设计端操作说明" aria-label="Permalink to &quot;设计端操作说明&quot;">​</a></h1><p>座位图设计器：在画布上绘制场馆分区、排与座位，配置类别 / 标签 / 水印，出票预览，并保存场馆数据。</p><blockquote><p>配图为本仓库开发环境实机截图（<code>docs/scripts/capture.mjs</code> 可重新生成）。截图中场馆为演示数据，实际使用请加载你们的真实场馆。</p></blockquote><h2 id="一、界面布局" tabindex="-1">一、界面布局 <a class="header-anchor" href="#一、界面布局" aria-label="Permalink to &quot;一、界面布局&quot;">​</a></h2><p>设计器自上而下、自左而右分五区：<strong>顶栏</strong>、<strong>工具栏</strong>、<strong>画布</strong>、<strong>侧栏</strong>、<strong>状态栏</strong>。 <img src="'+a+'" alt="设计器整体界面（空场馆）"></p><table tabindex="0"><thead><tr><th>区域</th><th>作用</th></tr></thead><tbody><tr><td>顶栏</td><td>场馆名、预览、主题切换、保存、撤销/重做、吸附开关、对齐/分布/翻转菜单、复制/粘贴/副本、删除</td></tr><tr><td>工具栏</td><td>绘制与编辑工具（详见下文）</td></tr><tr><td>画布</td><td>场馆绘制区域（Leafer canvas），支持缩放 / 平移 / 辅助线</td></tr><tr><td>侧栏</td><td>当前选中对象（分区 / 排 / 座位 / 底图 / 场馆）的属性编辑面板</td></tr><tr><td>状态栏</td><td>实时显示缩放比例、分区数、座位数、选中数</td></tr></tbody></table><p>加载一个真实场馆后，整体效果如下：</p><p><img src="'+c+'" alt="加载场馆后的整体视图"></p><h2 id="二、工作流程" tabindex="-1">二、工作流程 <a class="header-anchor" href="#二、工作流程" aria-label="Permalink to &quot;二、工作流程&quot;">​</a></h2><ol><li><strong>新建 / 加载场馆</strong>：顶栏左侧场馆列表新建或选择；也可由宿主调用 <code>newVenue()</code> / <code>setData(venue, seatlist)</code> 加载。</li><li><strong>上传底图（可选）</strong>：工具栏「底图」工具或侧栏上传，作为描图参照（可调透明度 / 缩放 / 锁定）。</li><li><strong>绘制分区</strong>：矩形分区（U）、圆形/椭圆分区（C）或自由多边形分区（P），画出场馆分区轮廓。</li><li><strong>绘制座位</strong>：单行座位（R）逐排绘制，或多行座位（G）一次生成多排；进入分区后可精细调整。</li><li><strong>配置类别与标签</strong>：类别管理设置价格区颜色；批量编号为排 / 座位编号；分区可配水印。</li><li><strong>保存</strong>：Ctrl+S 或顶栏保存按钮。首次保存走全量，之后只发增量（见<a href="./../backend-api.html">后端接口文档</a>）。</li></ol><h2 id="三、工具栏工具" tabindex="-1">三、工具栏工具 <a class="header-anchor" href="#三、工具栏工具" aria-label="Permalink to &quot;三、工具栏工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>快捷键</th><th>说明</th></tr></thead><tbody><tr><td>选择 Select</td><td><code>V</code></td><td>分区对象模式。单击选中分区/散座排，拖拽框选，拖动移动，双击进入分区；散座以排为单位</td></tr><tr><td>套索 Lasso</td><td><code>L</code></td><td>按住拖出自由笔画，<strong>路过的排/分区即选中</strong>（Shift 加选），松开完成；解决斜排/过道中段矩形框选选不中的问题；选中后拖动手柄旋转</td></tr><tr><td>座位选择 Seat</td><td><code>Q</code></td><td>座位模式。点选/框选座位，拖动移动，拖蓝色手柄旋转选区（Shift 吸附 15°）</td></tr><tr><td>节点编辑 Node</td><td><code>N</code></td><td>选中分区，拖顶点变形（网格四角/弧形角度半径），拖边中点调弧度；矩形支持等比缩放/边线缩放/角弧度</td></tr><tr><td>单行座位 Row</td><td><code>R</code></td><td>点击定起点 → 移动预览 → 再点击完成，可连续绘制</td></tr><tr><td>多行座位 Grid</td><td><code>G</code></td><td>三击完成：起点 → 首排 → 排数（垂直分量决定），一次生成多排</td></tr><tr><td>不规则分区 Poly</td><td><code>P</code></td><td>逐点连线，点回起点/双击闭合；<code>Backspace</code>/<code>Ctrl+Z</code> 撤销顶点；<code>Esc</code> 取消；只建轮廓</td></tr><tr><td>矩形分区 Rect</td><td><code>U</code></td><td>拖出矩形轮廓</td></tr><tr><td>圆形分区 Circle</td><td><code>C</code></td><td>拖出椭圆轮廓；按住 <code>Shift</code> 锁正圆；节点编辑拖 4 个方向手柄分别调横/纵半径；顶部旋转手柄可倾斜椭圆（旋转后双半径手柄保留）</td></tr><tr><td>底图 Image</td><td><code>I</code></td><td>上传底图；选中可移动/旋转/删除，侧栏调缩放/透明度/锁定</td></tr><tr><td>平移 Pan</td><td><code>H</code></td><td>拖拽平移画布（也可空格/中键）</td></tr></tbody></table><blockquote><p><strong>座位编辑模式下</strong>（双击进入分区后），分区类工具（节点/不规则分区/矩形分区/圆形分区/底图）自动禁用，仅保留：选择、座位选择、套索、单行、多行、平移。</p></blockquote><h3 id="套索工具" tabindex="-1">套索工具 <a class="header-anchor" href="#套索工具" aria-label="Permalink to &quot;套索工具&quot;">​</a></h3><p><img src="'+l+'" alt="套索工具激活"></p><p><strong>框选的用途 / 功能</strong>：框选是「先选后操作」的批量编辑入口——一次框选（矩形框选或套索）选中一组排 / 分区（座位编辑模式下为座位），随后可对整组统一<strong>移动、旋转、对齐 / 分布、删除</strong>（多选后顶栏「对齐 / 分布 / 翻转」菜单生效，按 <code>Delete</code> 批量删除），避免逐个操作。</p><p>套索适用于<strong>斜排 / 过道中段</strong>等矩形框选难以选中的座位。按住鼠标画出包围圈，笔画穿过的排/分区即被选中；Shift 加选，Esc 取消。</p><blockquote><p><strong>矩形框选 vs 套索</strong>：矩形框选只能扫过「规则矩形区域」内的对象（规整排布够用）；套索用自由笔画穿过目标，对斜排、过道拐角、弧形分区内的对象也能精确选中。两者选中的结果一致——都是得到一组可统一操作的对象。</p></blockquote><h3 id="节点编辑" tabindex="-1">节点编辑 <a class="header-anchor" href="#节点编辑" aria-label="Permalink to &quot;节点编辑&quot;">​</a></h3><p><img src="'+s+'" alt="节点编辑工具"></p><p>选中分区后切到节点工具，拖动轮廓顶点可整体变形，拖动边线中点调整弧形分区的弧度；矩形分区支持拖角点等比缩放、拖边线单边缩放、拖角调圆角；圆形/椭圆分区显示 4 个方向手柄——拖东西手柄调横向半径、拖南北手柄调纵向半径（双半径独立调整，圆心不动）。</p><h2 id="四、画布操作" tabindex="-1">四、画布操作 <a class="header-anchor" href="#四、画布操作" aria-label="Permalink to &quot;四、画布操作&quot;">​</a></h2><ul><li><strong>缩放</strong>：<code>Ctrl/Cmd + 滚轮</code>；也可用右下角缩放控件（+ / − 按钮、范围 0.02~25）。</li><li><strong>平移</strong>：按住空格或鼠标中键拖拽；<code>H</code> 工具；缩放控件的四向箭头与中心摇杆。</li><li><strong>吸附</strong>：顶栏「吸附」开关。拖动分区/底图时对齐参考线（分区边/中心线）；<code>Alt</code> 临时禁用，<code>Shift</code> 锁 45°。</li><li><strong>显示座位条</strong>：顶栏开关，控制座位编号条的显隐。</li><li><strong>对齐 / 分布 / 翻转</strong>：顶栏菜单——左中右对齐、上中下对齐、水平/垂直均匀分布、校正（straighten）、水平/垂直翻转，多选后使用。</li><li><strong>状态栏</strong>：实时显示缩放比例、分区数、座位数、选中数。</li></ul><h2 id="五、编辑操作" tabindex="-1">五、编辑操作 <a class="header-anchor" href="#五、编辑操作" aria-label="Permalink to &quot;五、编辑操作&quot;">​</a></h2><h3 id="分区对象模式-默认" tabindex="-1">分区对象模式（默认） <a class="header-anchor" href="#分区对象模式-默认" aria-label="Permalink to &quot;分区对象模式（默认）&quot;">​</a></h3><ul><li>单击选中，<code>Shift</code> 加选，画布拖框框选，<code>Ctrl+A</code> 全选。</li><li>拖动移动（带吸附）；拖旋转手柄旋转；<code>Delete</code> 删除（弹确认，可撤销）。</li><li>双击分区进入<strong>座位编辑模式</strong>；双击空白或按 <code>Esc</code> 退出。</li></ul><h3 id="座位编辑模式" tabindex="-1">座位编辑模式 <a class="header-anchor" href="#座位编辑模式" aria-label="Permalink to &quot;座位编辑模式&quot;">​</a></h3><p><img src="'+i+'" alt="座位编辑模式（面包屑提示正在编辑的分区）"></p><p>进入后画布顶部出现「✏ 正在编辑分区：××」面包屑，侧栏切到该分区的排/座位属性。框选座位可移动/旋转；排长手柄可拖拽增减座位（row-resize）；<code>Esc</code> 或「退出分区」按钮返回对象模式。</p><h3 id="框选-vs-套索" tabindex="-1">框选 vs 套索 <a class="header-anchor" href="#框选-vs-套索" aria-label="Permalink to &quot;框选 vs 套索&quot;">​</a></h3><ul><li><strong>框选</strong>：矩形扫过即选（适用于规整排布）。</li><li><strong>套索</strong>：自由笔画穿过命中（适用于斜排/过道中段）。</li></ul><p>正式分区优先于散座被选中。</p><h2 id="六、顶栏操作" tabindex="-1">六、顶栏操作 <a class="header-anchor" href="#六、顶栏操作" aria-label="Permalink to &quot;六、顶栏操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>快捷键</th><th>说明</th></tr></thead><tbody><tr><td>保存</td><td><code>Ctrl+S</code></td><td>保存当前场馆；只读场馆忽略。首次全量、之后增量。<strong>乐观锁</strong>：若他人已保存过同一场馆（版本冲突），按提示重新加载最新数据后再改</td></tr><tr><td>撤销 / 重做</td><td><code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code>、<code>Ctrl+Y</code></td><td>撤销/重做编辑操作；绘制不规则分区时 <code>Ctrl+Z</code>/<code>Backspace</code> 撤销顶点</td></tr><tr><td>全选</td><td><code>Ctrl+A</code></td><td>全选当前模式对象</td></tr><tr><td>复制 / 粘贴 / 副本</td><td><code>Ctrl+C</code> / <code>Ctrl+V</code> / <code>Ctrl+D</code></td><td>复制粘贴选中对象。<strong>粘贴结果超出座位上限（单分区 5,000 / 全场馆 80,000）时整体取消并提示「将超出全场馆座位上限」，不做部分裁剪</strong></td></tr><tr><td>删除</td><td><code>Delete</code> / <code>Backspace</code></td><td>删除选中对象（分区弹确认）</td></tr><tr><td>预览</td><td>—</td><td>打开出票预览弹窗</td></tr><tr><td>主题</td><td>—</td><td>浅色 / 深色切换</td></tr></tbody></table><h2 id="七、侧栏属性编辑" tabindex="-1">七、侧栏属性编辑 <a class="header-anchor" href="#七、侧栏属性编辑" aria-label="Permalink to &quot;七、侧栏属性编辑&quot;">​</a></h2><h3 id="分区属性" tabindex="-1">分区属性 <a class="header-anchor" href="#分区属性" aria-label="Permalink to &quot;分区属性&quot;">​</a></h3><p>选中分区后侧栏显示：座位数、角弧度（圆角矩形）、分区默认类别、标签样式（文本 / 可见 / 字号 / 旋转 / XY 偏移）、<strong>赞助商水印</strong>（文本 / Logo 图 / 颜色 / 宽度 / 透明度 / 字号 / 行距 / 旋转 / XY）。</p><p><strong>分区命名建议</strong>：命名可自带单位（如「东看台」「VIP区」），也可只写编号（如「7」）。用户端座位展示串（<code>X区Y排Z座</code>）会做<strong>单位后缀去重</strong>——名字已以单位字结尾（区/场/台/楼/层/厅/厢）就直接使用，否则自动补「区」：<code>7区</code> 显示「7区12排5座」、<code>7</code> 显示「7区12排5座」、<code>内场</code> 显示「内场12排5座」，不会出现「7区区」这类叠加。</p><h3 id="排属性" tabindex="-1">排属性 <a class="header-anchor" href="#排属性" aria-label="Permalink to &quot;排属性&quot;">​</a></h3><p>进入分区后选中排：座位数、旋转、弧度、排距（多排）、座位间距、对齐（左中右）、排标签（单排文本 / 首尾端位置）、座位编号摘要。</p><h3 id="座位属性" tabindex="-1">座位属性 <a class="header-anchor" href="#座位属性" aria-label="Permalink to &quot;座位属性&quot;">​</a></h3><p>选中座位：编号、类型（普通 / 椅子 / 凳子 / 长凳）、状态（可售 / 预留 / 已售 / 禁用）。</p><h3 id="场馆属性" tabindex="-1">场馆属性 <a class="header-anchor" href="#场馆属性" aria-label="Permalink to &quot;场馆属性&quot;">​</a></h3><p>场馆改名、类别数/座位数统计、<strong>检查清单</strong>、常驻图例。</p><p><strong>检查清单（6 项检测，点击标出 / 再点取消）</strong>：</p><table tabindex="0"><thead><tr><th>检测项</th><th>口径</th><th>标记效果</th></tr></thead><tbody><tr><td>分区重名</td><td>仅售票分区（空名不算，走「分区未命名」）</td><td>展开明细逐条标出全部同名分区</td></tr><tr><td>座位撞号</td><td>同分区内同排标签下编号重复</td><td>展开明细逐条标出所在分区</td></tr><tr><td>分区未命名</td><td>仅售票分区</td><td>一次标出全部未命名分区</td></tr><tr><td>排无标签</td><td>售票 + 散座分区</td><td>一次标出全部问题分区</td></tr><tr><td>座无编号</td><td>售票 + 散座分区</td><td>一次标出全部问题分区</td></tr><tr><td>座未分类</td><td>售票 + 散座分区</td><td>一次标出全部问题分区</td></tr></tbody></table><ul><li>点击清单行/明细条目后，问题对象以<strong>红色贴形描边</strong>标出（分区描轮廓、座位描圆、无标签排描整排），<strong>不自动跳转视图</strong>，处理顺序自定。</li><li><strong>模式感知</strong>：对象模式标到分区红框；双击进入分区编辑后自动细化为该分区内的具体座位/排红圈。</li><li>再点同一项取消标记；任何编辑或换场馆自动清除。标记期间状态栏常驻红字显示检测项与数量。</li><li>背景 / 装饰 / 舞台类分区不参与统计，不会产生误报。</li><li>载入时若检测到排已删除的残留座位（孤儿座位），状态栏提示数量，<strong>随下次保存自动清理</strong>（无需手动处理）。</li></ul><h2 id="八、类别与批量编号" tabindex="-1">八、类别与批量编号 <a class="header-anchor" href="#八、类别与批量编号" aria-label="Permalink to &quot;八、类别与批量编号&quot;">​</a></h2><h3 id="类别管理" tabindex="-1">类别管理 <a class="header-anchor" href="#类别管理" aria-label="Permalink to &quot;类别管理&quot;">​</a></h3><p><img src="'+n+'" alt="类别管理弹窗"></p><p>配置座位类别（价格区）：<code>key</code>、<code>color</code>（色板 + 自定义）、<code>label</code>、<code>price</code>。类别颜色即座位渲染颜色，价格供选座端合计。使用中的类别删除需行内确认。</p><h3 id="批量编号" tabindex="-1">批量编号 <a class="header-anchor" href="#批量编号" aria-label="Permalink to &quot;批量编号&quot;">​</a></h3><p><img src="'+h+'" alt="批量编号弹窗"></p><p>对排 / 分区 / 座位批量编号：</p><ul><li><strong>排/分区编号格式</strong>：字母（A,B,C…）/ 数字（1,2,3…）/ 罗马数字（I,II,III…）</li><li><strong>座位额外格式</strong>：奇偶（odd/even）、奇偶交替（oddEven）、镜像（mirror）、小写字母（alphaLower）</li><li>起始值、正向 / 反向、清除</li><li><strong>规则：每排独立从起始值编号</strong></li></ul><h2 id="九、快捷键总表" tabindex="-1">九、快捷键总表 <a class="header-anchor" href="#九、快捷键总表" aria-label="Permalink to &quot;九、快捷键总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>V</code> / <code>L</code> / <code>Q</code> / <code>N</code> / <code>R</code> / <code>G</code> / <code>P</code> / <code>U</code> / <code>C</code> / <code>I</code> / <code>H</code></td><td>切换对应工具</td></tr><tr><td><code>Shift</code>（圆形工具拖拽中）</td><td>锁正圆（横/纵半径相等）</td></tr><tr><td><code>Ctrl+S</code></td><td>保存</td></tr><tr><td><code>Ctrl+Z</code> / <code>Ctrl+Y</code>、<code>Ctrl+Shift+Z</code></td><td>撤销 / 重做</td></tr><tr><td><code>Ctrl+A</code></td><td>全选</td></tr><tr><td><code>Ctrl+C</code> / <code>Ctrl+V</code> / <code>Ctrl+D</code></td><td>复制 / 粘贴 / 生成副本</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>删除（绘制不规则分区时 = 撤销顶点）</td></tr><tr><td><code>Esc</code></td><td>关闭弹窗 → 取消本次绘制 → 退出分区 → 清空选区</td></tr><tr><td><code>Shift</code></td><td>加选；锁 45° / 15° 吸附</td></tr><tr><td><code>Alt</code></td><td>临时禁用吸附</td></tr><tr><td>空格 / 中键</td><td>平移画布</td></tr><tr><td><code>Ctrl/Cmd+滚轮</code></td><td>缩放画布</td></tr></tbody></table><blockquote><p>快捷键在输入框 / 文本框中不拦截（输入时优先）。</p></blockquote><h2 id="十、只读模式" tabindex="-1">十、只读模式 <a class="header-anchor" href="#十、只读模式" aria-label="Permalink to &quot;十、只读模式&quot;">​</a></h2><p>后端场馆标记 <code>readonly: 1</code> 时，设计器进入只读：顶栏隐藏保存按钮、忽略 <code>Ctrl+S</code>、显示「只读」徽标，所有编辑操作禁用。用于运营预览/审核场景。</p><h2 id="十一、大型场馆" tabindex="-1">十一、大型场馆 <a class="header-anchor" href="#十一、大型场馆" aria-label="Permalink to &quot;十一、大型场馆&quot;">​</a></h2><p><img src="'+g+'" alt="大型场馆（68 分区 / 3000+ 座位）全景"></p><p>设计器支持 4 万级座位的绘制与编辑。大场馆加载可分段喂数据（轮廓先上屏、座位后并入）以加快首屏；日常保存只发座位增量（KB 级），详见<a href="./../backend-api.html">后端接口文档</a>。</p>',63)])])}const P=d(p,[["render",b]]);export{C as __pageData,P as default};
